/*
 * A280866  Lexicographically earliest sequence of distinct terms such that,
 *          for any prime p, any run of consecutive multiples of p has at
 *          least length 2.
 * https://oeis.org/A280866
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a sequence is generated by a greedy algorithm. At each step pick
 *            the smallest unused integer that does not terminate a run of
 *            length 1 for any prime. see A280866
 * Range:     u8 n <= 168, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   get_prime_factors
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include "../utils/get_prime_factors.h"

/* ---------- local state ---------- */
static seq_t *sequence   = NULL;      /* sequence buffer            */
static size_t seq_len    = 0, seq_cap   = 0;

static unsigned char *used   = NULL;   /* bitmap of used numbers    */
static size_t used_cap = 0;

static uint8_t *run_len = NULL;        /* run length for each prime */
static size_t run_len_cap = 0;

static bool initialized = false;

/* ---------- helpers ---------- */

/* enlarge used bitmap if required */
static void ensure_used_cap(idx_t n)
{
    if ((size_t)n < used_cap) return;
    size_t new_cap = used_cap ? used_cap * 2 : 128;
    if (new_cap <= (size_t)n) new_cap = (size_t)n + 64;
    unsigned char *tmp = (unsigned char*)calloc(new_cap, sizeof(unsigned char));
    memcpy(tmp, used, used_cap);
    free(used);
    used = tmp;
    used_cap = new_cap;
}

/* enlarge run_len array so that index p is valid */
static void ensure_prime_cap(uint32_t p)
{
    if (p < run_len_cap) return;
    size_t new_cap = run_len_cap ? run_len_cap * 2 : 128;
    while (new_cap <= p) new_cap <<= 1;
    uint8_t *tmp = (uint8_t*)calloc(new_cap, sizeof(uint8_t));
    memcpy(tmp, run_len, run_len_cap);
    free(run_len);
    run_len = tmp;
    run_len_cap = new_cap;
}

/* initialise static data once */
static void init_sequence(void)
{
    if (initialized) return;

    used_cap = 128;
    used = (unsigned char*)calloc(used_cap, sizeof(unsigned char));

    run_len_cap = 128;
    run_len = (uint8_t*)calloc(run_len_cap, sizeof(uint8_t));

    seq_cap = 16;
    sequence = (seq_t*)malloc(seq_cap * sizeof(seq_t));

    /* first term is 1 */
    sequence[0] = (seq_t)1;
    seq_len   = 1;
    used[1] = 1;

    initialized = true;
}

/* ---------- public function ---------- */

seq_t a(idx_t n)
{
    /* 1-indexed: a(1) = 1 */
    init_sequence();

    while (seq_len < (size_t)n) {

        seq_t last = sequence[seq_len - 1];

        /* prime factors of the previous term */
        uint32_t last_pf[64];
        size_t last_cnt;
        get_prime_factors(last, last_pf, &last_cnt);
        for (size_t i = 0; i < last_cnt; ++i)
            ensure_prime_cap(last_pf[i]);

        /* search for the next lexicographically smallest valid number */
        idx_t candIdx = 2;
        while (1) {
            ensure_used_cap(candIdx);
            if (used[(size_t)candIdx]) {                /* already used */
                ++candIdx;
                continue;
            }

            /* check that this candidate does not invalidate
               any run of length 1 for the previous term */
            bool ok = true;
            for (size_t i = 0; i < last_cnt && ok; ++i) {
                uint32_t p = last_pf[i];
                if (candIdx % p != 0) {
                    if (run_len[p] == 1) ok = false;
                }
            }
            if (!ok) {
                ++candIdx;
                continue;
            }

            /* candidate found – update run lengths and store it */
            seq_t cand = (seq_t)candIdx;

            uint32_t cand_pf[64];
            size_t cand_cnt;
            get_prime_factors(cand, cand_pf, &cand_cnt);
            for (size_t i = 0; i < cand_cnt; ++i)
                ensure_prime_cap(cand_pf[i]);

            /* update runs for primes dividing the previous term */
            for (size_t i = 0; i < last_cnt; ++i) {
                uint32_t p = last_pf[i];
                if (candIdx % p == 0)
                    run_len[p] += 1;
                else
                    run_len[p] = 0;
            }

            /* start new runs for primes dividing the candidate only */
            for (size_t i = 0; i < cand_cnt; ++i) {
                uint32_t p = cand_pf[i];
                if (candIdx % p == 0 && last % p != 0)
                    run_len[p] = 1;
            }

            /* store the term */
            if (seq_len >= seq_cap) {
                seq_cap = seq_cap * 2;
                sequence = (seq_t*)realloc(sequence, seq_cap * sizeof(seq_t));
            }
            sequence[seq_len++] = cand;
            used[(size_t)candIdx] = 1;
            break;      /* next position ready */
        }
    }

    return sequence[(size_t)n - 1];
}
